"use strict";(self.webpackChunkdatabricks_monolith=self.webpackChunkdatabricks_monolith||[]).push([[4634],{282253:(e,t,o)=>{o.d(t,{$:()=>g,DZ:()=>d,KV:()=>n,K_:()=>f,M4:()=>i,XJ:()=>c,Xj:()=>u,Yq:()=>p,Zh:()=>k,br:()=>l,cw:()=>y,jl:()=>h,s4:()=>r,v9:()=>b,wm:()=>m});var a=o(342411),s=o(773848);let i="fundamentals-v2",n="catalog-explorer-foundation",r="create-notebook-ui",l="genie-code-notebooks",c="catalog-permissions-notebook",d=(0,a.YK)({courseTitle:{id:"+d6nGS",defaultMessage:"Fundamentals"},workspaceSurfaceLabel:{id:"hlGqnm",defaultMessage:"the Workspace"},catalogSurfaceLabel:{id:"p9g/4O",defaultMessage:"Catalog"},notebookSurfaceLabel:{id:"xx7Nnc",defaultMessage:"the Notebook Editor"},openHomePageCta:{id:"pXlrWm",defaultMessage:"Explore the Home page"},openSearchCta:{id:"0ttiIN",defaultMessage:"Search your workspace"},openWorkspaceBrowserCta:{id:"ExQUe5",defaultMessage:"Browse your workspace"},openComputeCta:{id:"ELTwhE",defaultMessage:"View Compute"},openSampleTableInCatalogExplorerCta:{id:"8JhwRk",defaultMessage:"Explore the sample table"},openProvisionedNotebookCta:{id:"6FVJq1",defaultMessage:"Open practice notebook"},lessonConclusionTitle:{id:"4qBb1f",defaultMessage:"Conclusion"},provisioningOverlayTitle:{id:"AJBugx",defaultMessage:"Loading course resources"},provisioningOverlayDataAssetsBody:{id:"c8owKM",defaultMessage:"Creating data assets..."},catalogProvisioningErrorTitle:{id:"A1LV0W",defaultMessage:"Unable to prepare lesson data"},catalogProvisioningErrorFallback:{id:"mUufK5",defaultMessage:"Please try again in a moment."},provisioningOverlayNotebookBody:{id:"Qg+SM5",defaultMessage:"Creating notebook..."},notebookProvisioningErrorTitle:{id:"MftGjY",defaultMessage:"Unable to create notebook"},homeBreadcrumb:{id:"4xi37H",defaultMessage:"Home"},openSidebar:{id:"+xi/NV",defaultMessage:"Open lesson sidebar"},collapseSidebar:{id:"uxWwl7",defaultMessage:"Collapse lesson sidebar"},parentNavigationAndUi:{id:"OqOuI+",defaultMessage:"Navigation and UI"},parentWorkspaceNavigation:{id:"rcv0og",defaultMessage:"Workspace Navigation"},parentCatalogExplorer:{id:"EZs/zw",defaultMessage:"Catalog Explorer"},lessonHomePageTitle:{id:"upxknF",defaultMessage:"Home Page"},lessonHomePageDestinationLabel:{id:"K0Ta6I",defaultMessage:"Explore the Home page"},lessonIntelligentSearchTitle:{id:"E/FoEv",defaultMessage:"Use Search to find Workspace Objects"},lessonIntelligentSearchDestinationLabel:{id:"wA92UL",defaultMessage:"Open Search"},lessonAssetsAndFoldersTitle:{id:"4k/TUb",defaultMessage:"Explore and Create Workspace Objects"},lessonAssetsAndFoldersDestinationLabel:{id:"tEr8bK",defaultMessage:"Open the Workspace browser"},lessonCatalogExplorerTitle:{id:"1J8uhd",defaultMessage:"Catalog Explorer UI + Structure and Foundation"},lessonCatalogExplorerDestinationLabel:{id:"8WDaBY",defaultMessage:"Open the sample table"},stepHomeIntroductionTitle:{id:"+bAPiV",defaultMessage:"Introduction"},stepHomeIntroductionContent:{id:"bQv+hI",defaultMessage:"This walkthrough helps you get around the Databricks Workspace UI and understand the navigation options at your fingertips."},stepHomeWalkthroughTitle:{id:"uYscbR",defaultMessage:"Home Page Walkthrough"},stepHomeYourResourcesTitle:{id:"T4MDcV",defaultMessage:"Your resources"},stepHomeNavigationSidebarTitle:{id:"PvQ/fW",defaultMessage:"Navigation Sidebar"},stepHomeNewTitle:{id:"+tbXTL",defaultMessage:"New"},stepHomeNewContent:{id:"ubcIWA",defaultMessage:"The + New button is the fastest way to create assets in the Databricks workspace. Objects you may want to create from here include: Notebooks, Queries, Dashboards, Genie Spaces, Jobs, and more. You can also add or upload data from this menu."},stepHomeComputeTitle:{id:"lIEWfs",defaultMessage:"Compute"},stepHomeComputeContent:{id:"F13Ww8",defaultMessage:"Compute in Free Edition is Serverless and is managed for you. From the Compute menu, you can view your SQL warehouses, Vector Search endpoints, and Apps within the platform. Note that there are limitations to the compute objects you can create in Free Edition."},stepHomeWorkspaceTitle:{id:"too5ra",defaultMessage:"Workspace"},stepHomeWorkspaceContent:{id:"1TN927",defaultMessage:"Workspace in the Navigation bar brings you to your Workspace browser where you can view, edit, share, and create Databricks objects such as notebooks, queries, dashboards, and more. Typically, the user who creates an object owns the object and is the only person or principal that can grant access to others in Databricks."},stepHomeCatalogTitle:{id:"huw1Qr",defaultMessage:"Catalog"},stepHomeCatalogContent:{id:"96aSrr",defaultMessage:"The catalog is your entry point to Catalog Explorer and Unity Catalog. This is where you can view data assets such as volumes, models, functions, and data tables. Items in Catalog Explorer are organized in the three-level namespace structure of catalogs, schemas, and data objects, which is the standard used by Databricks for referencing data objects. You can also view permissions details, history, and lineage from within the Catalog Explorer."},stepHomeNavSidebarSectionsTitle:{id:"GzIh6+",defaultMessage:"Navigation Sidebar Sections"},stepHomeNavSidebarSectionsContent:{id:"A6w/fk",defaultMessage:"In addition to the areas explored previously in this lesson, you will notice that the Navigation sidebar is organized into three core sections: SQL, Data Engineering, and AI/ML. These groups make it easy to navigate throughout the platform to the tools that you’ll need to use for your specific use case. Note that Databricks Agents are not available in Databricks Free edition."},stepIntelligentSearchIntroductionTitle:{id:"3KJDxp",defaultMessage:"Introduction"},stepIntelligentSearchIntroductionContent:{id:"AFZEFq",defaultMessage:"This walkthrough shows you how to use Search to locate items throughout the workspace."},stepIntelligentSearchBarTitle:{id:"AIujik",defaultMessage:"Search Bar: Top of Home page"},stepIntelligentSearchBarContent:{id:"PchmTc",defaultMessage:"The search bar provides quick search buttons for Notebooks, Tables, Jobs, Dashboards, or My assets. It also displays assets you have recently interacted with. You do not need to know the exact name of an object as you can also use natural language to search based on context. You can use exact names, partial names, or context statements and the search dropdown will change dynamically to showcase potential items that match your query. Use the object type and owner to help narrow down your search."},stepIntelligentSearchResultsTitle:{id:"h1/q99",defaultMessage:"Search Results Page"},stepAssetsIntroductionTitle:{id:"b0zPF0",defaultMessage:"Introduction"},stepAssetsIntroductionContent:{id:"ziRcoM",defaultMessage:"This walkthrough introduces you to the workspace browser and shows you how to create and manage assets in your workspace home."},stepAssetsWorkspaceTitle:{id:"M53Wav",defaultMessage:"Workspace"},stepAssetsCreateItemTitle:{id:"vry8yc",defaultMessage:"Create an Item"},stepAssetsUiFeaturesMenusTitle:{id:"+UuYgj",defaultMessage:"UI Features and Menus"},stepCatalogExplorerIntroductionTitle:{id:"QNTuWc",defaultMessage:"Introduction"},stepCatalogExplorerIntroductionContent:{id:"Aju12x",defaultMessage:"This walkthrough introduces you to Catalog Explorer, which is the main UI for interacting with Unity Catalog in a workspace."},stepCatalogExplorerNamespaceTitle:{id:"Y9oP4B",defaultMessage:"Catalog and the three-level namespace"},stepCatalogExplorerBrowseTitle:{id:"SNECuG",defaultMessage:"Browse Catalog Explorer"},stepCatalogExplorerBrowseContent:{id:"/+ImiE",defaultMessage:"Catalog Explorer uses a tree-style navigation to allow you to access different catalogs and the underlying schemas and data assets. If a schema contains more than one type of data asset, they will be separated by type in the navigation tree. In other environments, schemas are known as databases, but in Databricks, they contain more than just datasets. Catalogs have at least two standard schemas, default and information_schema. Default is an empty starting schema you can use when the catalog is created, and information_schema contains metadata views of the objects in the catalog."},stepCatalogExplorerCatalogTabsTitle:{id:"DwmDfy",defaultMessage:"Catalog tabs"},stepCatalogExplorerSchemaTabsTitle:{id:"Ttw83/",defaultMessage:"Schema tabs"},stepCatalogExplorerTableTabsTitle:{id:"6D7J+b",defaultMessage:"Table tabs"},stepCatalogExplorerPermissionsTitle:{id:"K28HfF",defaultMessage:"Settings Permissions"},parentNotebooks:{id:"KeEgVB",defaultMessage:"Notebooks"},lessonCreateNotebookUiTitle:{id:"owEL9b",defaultMessage:"Create a Notebook and Explore the Notebook UI"},lessonCreateNotebookUiDestinationLabel:{id:"Cgw9WY",defaultMessage:"Open practice notebook"},stepNotebookIntroductionTitle:{id:"ZmsXtH",defaultMessage:"Introduction"},stepNotebookIntroductionContent:{id:"cHlwNi",defaultMessage:"This walkthrough helps you create and navigate a Databricks notebook, understand its UI layout, and use core features like cells, markdown, focus mode, and visualizations."},stepNotebookCreateAndNameTitle:{id:"fIty2f",defaultMessage:"Create and Name a notebook"},stepNotebookWorkingWithCellsTitle:{id:"TO1DFE",defaultMessage:"Working with notebook cells"},stepNotebookMarkdownTitle:{id:"QHqLje",defaultMessage:"Markdown in notebooks"},stepNotebookSidebarOptionsTitle:{id:"cf/h0+",defaultMessage:"Left and Right Sidebar options"},stepNotebookExecutionOutputsTitle:{id:"P0fR75",defaultMessage:"Executing code and viewing outputs"},stepNotebookFocusModeTitle:{id:"u9P8/G",defaultMessage:"Focus mode"},stepNotebookVisualizationsTitle:{id:"T9+oJ3",defaultMessage:"Visualizations in Notebooks"},lessonAssistantNotebooksTitle:{id:"edPD7f",defaultMessage:"Databricks Assistant in Notebooks"},lessonAssistantNotebooksDestinationLabel:{id:"8aYzE7",defaultMessage:"Open practice notebook"},stepAssistantIntroductionTitle:{id:"LMZ8At",defaultMessage:"Introduction"},stepAssistantIntroductionContent:{id:"qDACXk",defaultMessage:"This walkthrough shows you how to use Databricks Assistant to generate code, write SQL, and diagnose errors directly inside your notebooks."},stepAssistantLocationTitle:{id:"DFz03L",defaultMessage:"Locating Assistant in Notebooks"},stepAssistantPythonTitle:{id:"nacX61",defaultMessage:"Writing Python with Assistant"},stepAssistantPythonContent:{id:"USUeqz",defaultMessage:"You can prompt Assistant to generate Python code by describing what you need in plain language. Assistant responds with a code snippet that you can insert into a new cell or accept and run in one step. For example, you can ask Assistant to “compute the sum of integers 1 through 10,” and it will generate a short Python snippet that you can immediately execute and verify."},stepAssistantSqlTitle:{id:"nIYtB+",defaultMessage:"Writing SQL with Assistant"},stepAssistantSqlContent:{id:"9xp1e0",defaultMessage:"Assistant can also generate SQL queries against your existing tables. When the notebook’s default language is Python, Assistant may respond with PySpark SQL unless you specify otherwise. A best practice is to include the language in your prompt. For example, ask it to “Use SQL to select the first 10 rows from my table.” The generated code should be written in the correct code type."},stepAssistantDebuggingTitle:{id:"72Mk8h",defaultMessage:"Debugging with Assistant"},stepAssistantBestPracticesTitle:{id:"w8MUgD",defaultMessage:"Assistant Best Practices"},lessonCatalogPermissionsNotebooksTitle:{id:"oFk6Q/",defaultMessage:"Explore Catalogs and Grant Permissions in Notebooks"},lessonCatalogPermissionsNotebooksDestinationLabel:{id:"rC/dAq",defaultMessage:"Open practice notebook"},stepNotebookCatalogIntroductionTitle:{id:"m4yrHm",defaultMessage:"Introduction"},stepNotebookCatalogIntroductionContent:{id:"DZwl4h",defaultMessage:"This walkthrough shows you how to interact with Unity Catalog from a notebook using SQL. You’ll check the current context, explore schemas, tables, and volumes, and grant permissions programmatically."},stepNotebookCatalogSetCatalogSchemaTitle:{id:"jXzKqU",defaultMessage:"Check current and set catalog and schema"},stepNotebookCatalogExploreSchemaTitle:{id:"FjwbVh",defaultMessage:"Explore the schema"},stepNotebookCatalogExploreTablesViewsTitle:{id:"O6AcQ7",defaultMessage:"Explore tables and views"},stepNotebookCatalogExploreVolumesTitle:{id:"FXm6t+",defaultMessage:"Explore volumes"},stepNotebookCatalogGrantPermissionsTitle:{id:"vkcYmG",defaultMessage:"Grant permissions in a Notebook"}}),p=[{id:"home-page",slug:"home-page",parentGroup:d.parentNavigationAndUi,title:d.lessonHomePageTitle,destinationLabel:d.lessonHomePageDestinationLabel,destinationRoute:"/",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725304/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=4fca31109436b21b51c04837124d09e58de51b941aa6a2b0a5f3813c0f1fd44f",vimeoId:"1169725304",contentType:"Interactive",introduction:{title:d.stepHomeIntroductionTitle,content:d.stepHomeIntroductionContent},steps:[{id:"walkthrough",title:d.stepHomeWalkthroughTitle,tryItOutLabel:d.openHomePageCta,markdownContent:`
You can access the home page in two ways:
- By clicking “Databricks” in the upper left corner of the UI, or
- By clicking “Home” in the navigation pane on the left.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725319/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=7f81ea486438edb8ebe62e41b6cafab7f79ea28f02be0f649d8b1cf3e7606ab5",vimeoId:"1169725319"},{id:"your-resources",title:d.stepHomeYourResourcesTitle,tryItOutLabel:d.openHomePageCta,markdownContent:`
“Your resources” provides quick access to assets across the workspace. It has three options in Free Edition and two additional options in a full workspace:
- **Suggested** - This surfaces recent assets you’ve interacted with.
- **Favorites** - This is a list of assets and items you’ve starred throughout the platform.
- **Popular** - This is a list of assets that have been receiving a high level of engagement from you or others in the workspace.
- **Mosaic AI** - This is a list of AI Models and features you can try on the platform. (Full Databricks version only.)
- **What’s New** - This is a list of recent features and releases and their related posts and notifications to help you learn more about Databricks. (Full Databricks version only.)
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725341/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=871b54d1d853161c327f21572ebe6049e89d39669a92da71f1c18ce0c536529a",vimeoId:"1169725341"},{id:"navigation-sidebar",title:d.stepHomeNavigationSidebarTitle,tryItOutLabel:d.openHomePageCta,markdownContent:`
The navigation sidebar is docked on the left side of the screen. The top items in the navigation are common entry points to areas throughout the platform that most users will engage with during their work.
The navigation sidebar can be minimized to increase your workspace viewing area by clicking the icon in the upper-left corner. The navigation can be viewed when you hover over the left side of the screen when it is collapsed. To bring it back, simply click the icon again.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725434/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=b9fad99a8ee088d4253c67311c393717486719069dda07ecb9fc997dc596a9ed",vimeoId:"1169725434"},{id:"new",title:d.stepHomeNewTitle,content:d.stepHomeNewContent,tryItOutLabel:d.openHomePageCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725412/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=4b34d92b1f419d1bc1f5fa2007ea016f2e514342fc5825ad92db6f49cbdcbf02",vimeoId:"1169725412"},{id:"compute",title:d.stepHomeComputeTitle,content:d.stepHomeComputeContent,tryItOutLabel:d.openComputeCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725365/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=91710305bb5bf81d9f87310e9223d1091735fd68fce0677ae2e22461dee6331f",vimeoId:"1169725365",destinationRoute:"/compute"},{id:"workspace",title:d.stepHomeWorkspaceTitle,content:d.stepHomeWorkspaceContent,tryItOutLabel:d.openWorkspaceBrowserCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725375/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=29404c77efc06c1d7449ab5397b895fc2346c7bb1e4b094835e78a23c498b1f5",vimeoId:"1169725375",destinationRoute:"/browse"},{id:"catalog",title:d.stepHomeCatalogTitle,content:d.stepHomeCatalogContent,tryItOutLabel:d.openHomePageCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725404/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=b83c9912ef012e2565f7e136289d02f82139968b1d016e3468dfcf7becbf82e0",vimeoId:"1169725404"},{id:"nav-sidebar-sections",title:d.stepHomeNavSidebarSectionsTitle,content:d.stepHomeNavSidebarSectionsContent,tryItOutLabel:d.openHomePageCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725443/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=6eb8e2ea47869bb46eb75589416eb55604da83de03c897f627ac4d2478cfc337",vimeoId:"1169725443"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Navigate the Lakehouse workspace UI homepage.
- Identify the different UI screens associated with Compute, Workspace, and Catalog.
- Access objects you own and data assets in Unity Catalog.

**Resource Links**

- [Workspace UI | Databricks on AWS](https://docs.databricks.com/aws/en/workspace)
- [Navigate the Lakehouse workspace UI | Databricks on AWS](https://docs.databricks.com/aws/en/workspace/navigate-workspace)
- [Workspace browser | Databricks on AWS](https://docs.databricks.com/aws/en/workspace/workspace-browser)
- [What is Catalog Explorer? | Databricks on AWS](https://docs.databricks.com/aws/en/catalog-explorer)
- [Databricks Free Edition limitations](https://docs.databricks.com/aws/en/getting-started/free-edition-limitations)
`}},{id:"intelligent-search",slug:"intelligent-search",parentGroup:d.parentNavigationAndUi,title:d.lessonIntelligentSearchTitle,destinationLabel:d.lessonIntelligentSearchDestinationLabel,destinationRoute:"/search",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725354/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=e57305650ab0d3f26d76f1f8bac9f28f7591c7dcf651e65597b443f269d8a4d3",vimeoId:"1169725354",contentType:"Interactive",introduction:{title:d.stepIntelligentSearchIntroductionTitle,content:d.stepIntelligentSearchIntroductionContent},steps:[{id:"search-bar",title:d.stepIntelligentSearchBarTitle,content:d.stepIntelligentSearchBarContent,tryItOutLabel:d.openSearchCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725396/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=8c92d97db6984630ee759a5ba5a4cd557c2c7bede554ed5936192536fc10a4bd",vimeoId:"1169725396"},{id:"search-results",title:d.stepIntelligentSearchResultsTitle,tryItOutLabel:d.openSearchCta,markdownContent:`
When you hit **Enter** when typing in the search bar, you are taken to a Search Results page. This page provides a larger view of the potential results to your query. You can also filter your results based on additional criteria, such as an expanded list of asset types, assets specifically owned by you, or whether or not the item is classified as **Certified**. The tiles on the page include information about the asset to help you narrow down your search, including the owner, the location, when the asset was last modified, and additional tags and details that may be relevant in helping you find the right item. 
Selecting an item opens it in the same browser window, but you can use **Cmd + Click** (Mac) or **Ctrl + Click** (Windows/Linux) to open it in a new browser tab. `,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1169725385/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=e105f592a71797e56bf965ff16b6fcfeb318c2d818d834e453c540ebaa788168",vimeoId:"1169725385"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Search for assets with the search bar at the top of the Workspace UI.
- Use the search results page to refine your search by viewing additional asset information.
- Leverage filters on the search results page to narrow down your results based on different features and qualities of items in the platform.
- Enter a query using natural language or context terms to search using semantic information instead of exact asset names.

**Resource Links**

- [Search for workspace objects | Databricks on AWS](https://docs.databricks.com/aws/en/search/)
`}},{id:"assets-and-folders",slug:"assets-and-folders",parentGroup:d.parentWorkspaceNavigation,title:d.lessonAssetsAndFoldersTitle,destinationLabel:d.lessonAssetsAndFoldersDestinationLabel,destinationRoute:"/browse",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170788592/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=12631cd578b3f32ee3f83e5079215f48443a7e2def7ccbe80d0a12e09cd7ba7f",vimeoId:"1170788592",contentType:"Interactive",introduction:{title:d.stepAssetsIntroductionTitle,content:d.stepAssetsIntroductionContent},steps:[{id:"workspace",title:d.stepAssetsWorkspaceTitle,tryItOutLabel:d.openWorkspaceBrowserCta,markdownContent:`
By clicking “Workspace” in the Navigation sidebar on the left of your screen, you will access the Workspace Browser home area. Home is the starting point for all your personal assets and folders. The icon next to the workspace object indicates the object's type. Data assets, such as tables, models, volumes, and stored functions, are in Catalog Explorer, not the Workspace folder. Additional areas of the Workspace browser include:
- **Shared with me** - Assets and objects shared with you from other users.
- **Workspace** - this is the root folder for the workspace and includes subfolders for Repos, Shared, and Users, of which you are one. You’ll only have access to other users’ folders if you have appropriate permissions.
- **Favorites** - Objects you have starred across the platform will be listed here.
- **Trash** - Objects you’ve deleted will be visible in this area and can be restored or permanently deleted. Items are only held in the Trash folder for up to 30 days before being permanently deleted.
The viewing area for assets lets you search the folder and filter by type, owner, or last modified date.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170788657/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=aca6c6e0b8a39e23b4e377ccc26394881447e6c3cf94481b8f1fa5c552abb55c",vimeoId:"1170788657"},{id:"create-item",title:d.stepAssetsCreateItemTitle,tryItOutLabel:d.openWorkspaceBrowserCta,markdownContent:`
You can create a new folder or object anywhere you have write access. To create a new folder or object, you can either:
- Click **Create** and select the type of object.
- **Right-click** the base folder, select **Create**, and then the type of object.
- Click **+ New** from the Navigation sidebar. Note that this will create the item in the home folder, and you may need or want to move it to its final destination after you’ve created it.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170788642/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=12558383b982273dbd423dc06ebd063dae795e1a4561d37057c54e2469dc04a4",vimeoId:"1170788642"},{id:"ui-features-menus",title:d.stepAssetsUiFeaturesMenusTitle,tryItOutLabel:d.openWorkspaceBrowserCta,markdownContent:`
The Workspace Browser has the following features to assist you with navigation and management:
- Breadcrumb navigation at the top
- Separate menus for individual assets and the overall folder
- Drag and drop reorganization support and a Move dialog box to dynamically choose where to relocate an asset
- Individual object and folder sharing capabilities
- Object deletion options
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170788619/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=18f3b57fd31f5f082967dde7cd02c0919ccd1750d44f58641348b6b567fcbc69",vimeoId:"1170788619"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Navigate the Workspace browser.
- Create new objects within your workspace folder.
- Relocate objects between folders.
- Share workspace objects with others.
- Delete workspace objects temporarily and permanently.

**Resource Links**

- [Introduction to workspace objects | Databricks on AWS](https://docs.databricks.com/aws/en/workspace/workspace-assets)
- [Workspace browser | Databricks on AWS](https://docs.databricks.com/aws/en/workspace/workspace-browser)
- [Manage workspace objects | Databricks on AWS](https://docs.databricks.com/aws/en/workspace/workspace-objects)
- [Workspace files basic usage | Databricks on AWS](https://docs.databricks.com/aws/en/files/workspace-basics)
`}},{id:n,slug:"catalog-explorer",parentGroup:d.parentCatalogExplorer,title:d.lessonCatalogExplorerTitle,destinationLabel:d.lessonCatalogExplorerDestinationLabel,destinationRoute:"/explore/data/dbacademy/default/winequality_red",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790305/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=a2797a548ecf8a9c1c8922434819aaabc9343a3a4ce82913db62edf0847b4c81",vimeoId:"1170790305",contentType:"Interactive",needsProvisioning:!0,introduction:{title:d.stepCatalogExplorerIntroductionTitle,content:d.stepCatalogExplorerIntroductionContent},steps:[{id:"namespace",title:d.stepCatalogExplorerNamespaceTitle,tryItOutLabel:d.openSampleTableInCatalogExplorerCta,markdownContent:"To access the Catalog Explorer, click **Catalog** from the Navigation sidebar. Databricks utilizes a three-level namespace to organize and manage data assets. To reference data assets within code, you would need to use the following reference structure: **catalog.schema.data-object**. The catalog is the top-level container. Schemas are logical containers under the catalog. Schemas can contain tables, volumes, models, and stored functions.",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790407/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=2f260283d5a9e7d1746cdd0117b97a16ebc530937d5398bda79c182fd60873bb",vimeoId:"1170790407"},{id:"browse-catalog-explorer",title:d.stepCatalogExplorerBrowseTitle,content:d.stepCatalogExplorerBrowseContent,tryItOutLabel:d.openSampleTableInCatalogExplorerCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790424/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=ae55cafbcc7b04ce15eb08f4d1731735e66a1aa32603e627a792f6ebbb5536e0",vimeoId:"1170790424"},{id:"catalog-properties",title:d.stepCatalogExplorerCatalogTabsTitle,tryItOutLabel:d.openSampleTableInCatalogExplorerCta,markdownContent:`
The Catalog view has the following tabs:
- **Overview** - Includes a catalog description and list of included schemas. You can use AI to generate detailed descriptions for a catalog to speed up the annotation of your catalogs.
- **Details** - Shows technical metadata regarding the catalog
- **Permissions** - Grant or revoke permissions at the catalog level
- **Policies** - Attach catalog-level row or column filters that will be inherited down to the schemas and data objects below
- **Workspaces** - A list of workspaces this catalog is included in
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790392/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=03c755db56d299b9af6dbdc5170d32dcee763af462c4f617f596169f3ea8a7ed",vimeoId:"1170790392"},{id:"schema-properties",title:d.stepCatalogExplorerSchemaTabsTitle,tryItOutLabel:d.openSampleTableInCatalogExplorerCta,markdownContent:`
The Schema view has the following tabs:
  - **Overview** - Includes a schema description and a view of the tables, volumes, models, and functions within the schema.
  - **Details** - Shows technical metadata regarding the schema
  - **Permissions** - Grant or revoke permissions at the schema level
  - **Policies** - Attach schema-level row or column filters that will be inherited by the data objects within the schema
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790439/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=5338b594faa7fa43ab87f51abd899a25b343011952e091f773eb1c6932640808",vimeoId:"1170790439"},{id:"table-properties",title:d.stepCatalogExplorerTableTabsTitle,tryItOutLabel:d.openSampleTableInCatalogExplorerCta,markdownContent:`
The Table view has the following tabs:
  - **Overview** - Includes a description and a list of columns in the table. You can use AI to add a description and column comments. You can also add tags to the columns.
  - **Sample Data** - A simple \`SELECT * FROM table_name\` query to preview the data in the table.
  - **Details** - Shows technical metadata for the table, including the owner and data type, as well as whether the table is managed.
  - **Permissions** - Grant or revoke permissions at the table level
  - **Policies** - Attach table-level row or column filters that will mask row or column data based on an individual's or group's permissions
  - **History** - This is an audit log of all the changes and edits that have been made to the table.  
  - **Lineage** - This view shows the upstream and downstream dependencies for the table. It can be viewed in either a table or a graph. 
  - **Insights** - Surfaces usage information such as where the table is used most frequently and who accesses the table most often.
  - **Quality** - When quality monitoring is enabled, this displays freshness and completeness check information and any details regarding anomalies in the dataset.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790360/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=51eb2cc5ee3ce5c7dbae4fc560ae0d81f11a9841b8baeec4f433a7d89f06aac3",vimeoId:"1170790360"},{id:"permissions",title:d.stepCatalogExplorerPermissionsTitle,tryItOutLabel:d.openSampleTableInCatalogExplorerCta,markdownContent:`
From the permissions tab you can grant or revoke permissions to others on data assets and objects such as catalogs, schemas, and tables. The UI provides an easy click and select way to provide these permissions.
In order for principals, users, or groups to be able to access a data asset, either to view, use, or edit the asset, they must also have USE permissions on the parent schema and parent catalog up the hierarchy. The UI does warn you of this requirement when attempting to grant permissions with upstream privilege requirements.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1170790463/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=76deec55ba1497c13302aa5b0d81d943105829742b1cfdba8ed4502688f90650",vimeoId:"1170790463"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Access the Catalog Explorer in the Databricks Workspace UI.
- Recognize the three-level namespace for referencing data objects throughout the platform.
- Navigate the catalog, schema, and table UI options.
- Set permissions on data assets using the Catalog Explorer UI.
- Identify when additional upstream permissions are needed to access a data object appropriately.

**Resource Links**

- [What is Catalog Explorer? | Databricks on AWS](https://docs.databricks.com/aws/en/catalog-explorer)
- [Unity Catalog privileges and securable objects | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)
- [Explore database objects | Databricks on AWS](https://docs.databricks.com/aws/en/discover/database-objects)
- [Database objects in Databricks | Databricks on AWS](https://docs.databricks.com/aws/en/database-objects/)
- [Manage privileges in Unity Catalog | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/)
- [Access control in Unity Catalog | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control)
`}},{id:r,slug:"create-notebook-ui",parentGroup:d.parentNotebooks,title:d.lessonCreateNotebookUiTitle,destinationLabel:d.lessonCreateNotebookUiDestinationLabel,destinationRoute:"/",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893525/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=8b53cea95475365e1f50c48251b09d03ce0bd0e56e39fae17d8a7e8f219f59e8",vimeoId:"1171893525",contentType:"Interactive",needsProvisioning:!0,introduction:{title:d.stepNotebookIntroductionTitle,content:d.stepNotebookIntroductionContent},steps:[{id:"create-and-name-notebook",title:d.stepNotebookCreateAndNameTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
You can create a notebook in three ways:
- In the Workspace browser, right click on the folder you want to add a notebook to, and select Create then Notebook.
- After navigating to the folder you want to add a notebook to, click Create in the upper right of the screen and select Notebook.
- Click + New from the navigation and select Notebook. This creates a new notebook in your default home folder.
New notebooks have a temporary name. Click the title at the top of the notebook to rename it. After creating a notebook, you can use the compute selector in the upper right to attach it to a cluster or SQL Warehouse. In Free Edition, serverless compute is your only option and will start automatically when you run a cell.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893574/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=052dfe45d1f5fd96b026576210ef12a1f955f42be8c2afc123a361eeeead2e60",vimeoId:"1171893574"},{id:"working-with-notebook-cells",title:d.stepNotebookWorkingWithCellsTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
Between cells you're able to select **+ Code**, **+ Text**, or **Assistant** to insert a new cell. Code cells can be run by selecting the **Run**, or play, button on the left upper corner of the cell or by pressing **Shift + Enter**.
Every notebook has a default language indicated at the top next to the Help menu. Databricks notebooks support **Python** and **SQL**. New cells are created in the default language, but you can change each cell individually by using the dropdown in the upper-right corner of the cell. Changing the language of a cell adds a magic mark (%py, %sql, %md) at the top of the cell.
If you have the tabs experience enabled for notebooks in Settings, each notebook opens in its own tab which allows you to switch between multiple notebooks without returning to the Workspace browser. You can also rearrange these tabs by dragging and dropping.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893745/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=02eaaa11cdcc6073893343c63b22e7dba3b8f4feca2314dad6e707fad7410cae",vimeoId:"1171893745"},{id:"markdown-in-notebooks",title:d.stepNotebookMarkdownTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
Markdown cells are used for documentation such as headings, bullet point lists, links, and tables. To create a markdown cell, you can either click **+ Text**, change the cell type to markdown from the language switcher, or type **%md** at the top of the cell.
Double-click into a markdown cell to edit it and use **Show Preview** to view the rendering side by side with the text you are editing.
Well-structured markdown headings automatically populate to the **Table of Contents** panel on the left of a notebook, making longer notebooks easier to navigate by simply clicking the heading in the **Table of Contents**.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893628/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=9581da10610fb8d6710f504ff195c6b9f0d7ec5bdecc5b5ae7b64b7184e099d8",vimeoId:"1171893628"},{id:"sidebar-options",title:d.stepNotebookSidebarOptionsTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
The left sidebar navigation of a notebook includes:
- **Table of Contents** - The heading structure of the notebook based on the included markdown.
- **Folder icon** - Opens the workspace browser in a side panel for navigating to other notebooks and assets in your workspace folders.
- **Catalog icon** - A compact view of the Catalog Explorer, where you can browse catalogs, schemas, tables, and volumes. You can even use this to insert references directly into your code.
The right sidebar includes shortcuts for: Comments, MLflow experiments, Version history, Variables, Environment (related to the compute), Information, and Assistant. These tools help you to annotate, track experiments, and inspect the notebook state as you work.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893808/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=caa5980ab801f98878e05b0fb3bc1c8ed1b05aa191cc516c149f840c620c5cb5",vimeoId:"1171893808"},{id:"executing-code-and-viewing-outputs",title:d.stepNotebookExecutionOutputsTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
When you run a code cell, the output is displayed directly beneath the cell. For cells not in the notebook default, remember to include the magic command to ensure the runtime executes correctly when the cell is encountered. You can run individual cells with the **Run** button or **Shift + Enter**, or you can use **Run All** in the notebook toolbar to execute every cell from top to bottom in sequence.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893845/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=107d1f5e41a2e76ecdc7b998d2d8114b89e326ace5c71089e5db32bbe8aeb58f",vimeoId:"1171893845"},{id:"focus-mode",title:d.stepNotebookFocusModeTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
**Focus mode** expands a single cell and its results to fill the notebook view, removing distractions from surrounding cells. The Focus mode icon is in the upper-right corner of a cell. You will still have access to comments, Assistant, and the terminal panel while in Focus mode. 
You can also navigate between cells without closing focus mode by using the **right** and **left arrows** at the top of the window.
Click the icon again to exit Focus mode and return to the full notebook view.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893827/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=03b09a8bb2fea4b81610e46417df815d6f141b3751941cef69f59f890ab07760",vimeoId:"1171893827"},{id:"visualizations",title:d.stepNotebookVisualizationsTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
After running a cell that returns tabular results, you can click the **+ icon** next to the cell results to create a visualization directly alongside your output. You can configure the chart type, such as bar, scatter, or line, set the X and Y values, and save the visualization. Once saved, you can switch back and forth between the results table and the visualization within the same cell.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893674/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=cb0bf81d05e7e2574a215bb9de1d0dd09501fba7fa010e43d0ccca0e461685fe",vimeoId:"1171893674"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Create and rename a notebook and attach compute.
- Insert and run a code cell using multiple languages.
- Use markdown cells to document and navigate your notebook.
- Navigate the options in the left and right sidebars of the notebook UI.
- Use Focus mode to concentrate on a single cell and its results.
- Create inline visualizations from cell output.

**Resource Links**

- [Databricks notebooks | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/)
- [Develop code in Databricks notebooks | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/notebooks-code)
- [Navigate the Databricks notebook and file editor | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/notebook-editor)
`}},{id:l,slug:"genie-code-notebooks",parentGroup:d.parentNotebooks,title:d.lessonAssistantNotebooksTitle,destinationLabel:d.lessonAssistantNotebooksDestinationLabel,destinationRoute:"/",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893495/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=6929f3ccb948bb6cb34a42a945ba50338adf7e826f7a16e343d44611139a0fc9",vimeoId:"1171893495",contentType:"Interactive",needsProvisioning:!0,introduction:{title:d.stepAssistantIntroductionTitle,content:d.stepAssistantIntroductionContent},steps:[{id:"locating-assistant",title:d.stepAssistantLocationTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
There are several ways to open Assistant in a notebook:
- Click the **Assistant icon** in the right sidebar to open the chat panel alongside your notebook.
- Use the **Assistant button** in the top navigation bar to also open the chat side panel.
- Click the **inline Assistant button** between cells to open Assistant within the new cell.
The sidebar chat panel stays open as you work, allowing you to interact with Assistant while writing and running code.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893616/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=53e933f1b4747c0279541b7f4a3f9408a965b71e078ba0a33184c6ad4e398d14",vimeoId:"1171893616"},{id:"writing-python-with-assistant",title:d.stepAssistantPythonTitle,content:d.stepAssistantPythonContent,tryItOutLabel:d.openProvisionedNotebookCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893761/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=9cb8ece415644ffd9d42deac992929fc22ac28aae9588e2db3b8e8418201e1d9",vimeoId:"1171893761"},{id:"writing-sql-with-assistant",title:d.stepAssistantSqlTitle,content:d.stepAssistantSqlContent,tryItOutLabel:d.openProvisionedNotebookCta,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893688/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=b6b99803344510995719bd1655e7f5b99463dabce5540081700f1b68b3d7389d",vimeoId:"1171893688"},{id:"debugging-with-assistant",title:d.stepAssistantDebuggingTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
When a cell fails, the notebook UI displays a **Diagnose Error** option if **Assistant Quick Fix** is enabled. Clicking the **Diagnose Error** button sends the failing code and the error message to Assistant which opens in the side panel. It will then explore the error and provide an explanation of what it believes went wrong and provide a suggested fix. From the assistant side panel, you can run the suggested code to test it or edit the suggestion if you have additional context. Sometimes fixing one problem reveals another, so you may need to do more diagnosis to fully resolve the whole issue.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893556/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=bbdb5e1502de2a84c2a4b17bd6f9893d21870d80424abfe62bd5a68b412db83e",vimeoId:"1171893556"},{id:"assistant-best-practices",title:d.stepAssistantBestPracticesTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:`
Assistant is powerful, but keep in mind these best practices:
- Always review generated code and outputs before using them in production or sharing them with others.
- Be specific in your prompts including table names, columns, and the language you want for a more accurate result.
- If an error persists, review the full stack trace alongside Assistant’s explanation. Together these may help you pinpoint the exact table, schema, or privilege that is missing or incorrect.
Assistant is integrated throughout the platform, so as you explore, look for places where it can support your development work.
`,videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893660/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=6ee612a746be3ab1129e24fdb279a925375c55f3e80c2364761c03e5a64e7e67",vimeoId:"1171893660"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Open and interact with Genie Code from multiple access points in a notebook.
- Generate Python and SQL code using natural language prompts.
- Use the Diagnose Error feature to debug failing cells.
- Apply best practices for prompt specificity and code review when using Genie Code.

**Resource Links**

- [Use Genie Code | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/use-databricks-assistant)
- [Genie Code | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/databricks-assistant-faq)
- [Get coding help from Genie Code | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/code-assistant)
- [Tips to improve Genie Code responses | Databricks on AWS](https://docs.databricks.com/aws/en/notebooks/assistant-tips)
`}},{id:c,slug:"catalog-permissions-notebook",parentGroup:d.parentNotebooks,title:d.lessonCatalogPermissionsNotebooksTitle,destinationLabel:d.lessonCatalogPermissionsNotebooksDestinationLabel,destinationRoute:"/",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893461/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=fd28fb37be722881738b3ab824b3efd14d0bcc918fb38268613aac810564a0d4",vimeoId:"1171893461",contentType:"Interactive",needsProvisioning:!0,introduction:{title:d.stepNotebookCatalogIntroductionTitle,content:d.stepNotebookCatalogIntroductionContent},steps:[{id:"check-current-and-set-catalog-schema",title:d.stepNotebookCatalogSetCatalogSchemaTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:"\nUsing `SELECT current_catalog(), current_schema();` allows you to confirm which catalog and schema your notebook is currently using. This is especially useful in longer notebooks where you may have lost track of the active context. You can change your context with **USE CATALOG** and **USE SCHEMA** statements. Knowing your current context tells you whether or not you need to fully qualify table names or you can rely on the defaults.\n",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893596/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=3a6448a0a2cd5a5c380e2e72ed40b5c6a280dbb77647352f5eca4a2989317194",vimeoId:"1171893596"},{id:"explore-the-schema",title:d.stepNotebookCatalogExploreSchemaTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:"\nTo view the details of a schema programmatically, you can use `DESCRIBE SCHEMA EXTENDED current_schema();`. The result shows properties such as the schema owner, storage location, and any comments or custom properties that have been set, giving you a quick overview of the schema’s configuration.\n",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893707/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=03edbde37cdde96642367877ef1e63c15dae47ded520714954916a68fca6d933",vimeoId:"1171893707"},{id:"explore-tables-and-views",title:d.stepNotebookCatalogExploreTablesViewsTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:"\nUse `SHOW TABLES;` to list all tables and views in the current schema. The output includes each tables’s name, type, and comments to help you understand what is available for use. Views are listed alongside tables which is important to keep in mind when exploring dependencies between objects and whether or not something can be edited.\n",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893780/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=50cc498187808c6537dcfa40a50a92252f6fe9a7e5470fdce95e963ef6811f35",vimeoId:"1171893780"},{id:"explore-volumes",title:d.stepNotebookCatalogExploreVolumesTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:"\nRun `SHOW VOLUMES;` to list all logical volumes registered in the current catalog and schema, including their names and storage locations. For a specific volume, you can run a command to list all the files in its path to see what raw files are available for ingestion or processing.\n",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893729/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=80d89f99c53fc62b6272269f3806469fba9cbff377a07c057fb6ed72ce734ef9",vimeoId:"1171893729"},{id:"grant-permissions",title:d.stepNotebookCatalogGrantPermissionsTitle,tryItOutLabel:d.openProvisionedNotebookCta,markdownContent:"\nUnity Catalog uses ANSI-style GRANT statements to manage permissions directly from a notebook. For example, you can grant `SELECT` on a table to all account users with a single SQL statement. Unity Catalog enforces a hierarchical privilege model where users will also need `USE CATALOG` and `USE SCHEMA` privileges on the parent containers in order to query the table. You can verify your grants by running `SHOW GRANTS` or by checking the Permissions tab in Catalog Explorer. The recommended pattern is to use SQL in notebooks to automate permission changes when necessary and use Catalog Explorer to visually confirm they are applied correctly.\n",videoUrl:"https://player.vimeo.com/progressive_redirect/playback/1171893642/rendition/1080p/file.mp4%20%281080p%29.mp4?loc=external&signature=f5f42a13d4ae29ef0ca5d69d6f5e85975559d167b24a7d63cbb80bb608ac945c",vimeoId:"1171893642"}],conclusion:{title:d.lessonConclusionTitle,markdownContent:`
In this lesson you learned how to:

- Check and set the current catalog and schema context for a notebook.
- Use SQL to explore schemas, tables, views, and volumes in Unity Catalog.
- Grant permissions on data assets programmatically using \`GRANT\` statements.
- Verify permissions using both SQL and the Catalog Explorer UI.
- Explain the hierarchical privilege model and upstream permission requirements enforced by Unity Catalog.

**Resource Links**

- [What is Unity Catalog? | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/)
- [Unity Catalog privileges and securable objects | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/privileges)
- [Manage privileges in Unity Catalog | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/manage-privileges/)
- [Access control in Unity Catalog | Databricks on AWS](https://docs.databricks.com/aws/en/data-governance/unity-catalog/access-control)
- [What are catalogs in Databricks? | Databricks on AWS](https://docs.databricks.com/aws/en/catalogs/)
- [What are Unity Catalog volumes? | Databricks on AWS](https://docs.databricks.com/aws/en/volumes)
`}}],u=p.length,h=e=>p.findIndex(t=>t.id===e.id),b=e=>void 0!==e.tryItOutLabel,g=e=>{let t=e.steps.findIndex(b);return -1===t?null:t},m=e=>p.find(t=>t.id===e),f=e=>p.find(t=>t.slug===e),k=(e,t)=>e.steps.map(o=>({id:`${e.id}-${o.id}`,stepId:o.id,title:t.formatMessage(o.title),content:o.markdownContent??(o.content?t.formatMessage(o.content):void 0),videoUrl:o.videoUrl??e.videoUrl,vimeoId:o.vimeoId??e.vimeoId,...o.destinationRoute?{destinationRoute:o.destinationRoute}:{}})),y=(e,t,o)=>{let a=h(e),n=a>=0&&a<p.length-1?p[a+1]:void 0;return{sessionKind:"fundamentals",moduleId:i,moduleTitle:t,lessonId:e.id,lessonTitle:o.formatMessage(e.title),destinationRoute:e.destinationRoute,destinationLabel:o.formatMessage(e.destinationLabel),backToCourseRoute:(0,s.K)(e.slug),steps:k(e,o),totalModules:p.length,needsProvisioning:e.needsProvisioning,nextLessonSession:n?y(n,t,o):void 0}}}}]);
//# sourceMappingURL=https://sourcemaps.dev.databricks.com/monolith/static/js/4634.b2ca9dfd5c.chunk.js.map